(
    item: InspectionFormItem,
    idx: number,
    cur: ItemState,
    shown: readonly number[],
  ) => (
    <div className="grid grid-cols-4 gap-1 rounded-md border p-2 sm:grid-cols-6">
      {shown.map((no) => {
        const locked = carriedHere(idx, no);
        const isFail = cur.failed.has(no) || locked;
        return (
          <button
            key={no}
            type="button"
            disabled={disabled || locked}
            aria-pressed={isFail}
            title={
              locked
                ? CARRIED_TITLE(no)
                : `${item.label} ${sampleLabel(no)}: 눌러서 ${isFail ? "합격" : "부적합"} 으로`
            }
            onClick={() => toggle(item.key, no)}
            className={cn(
              "rounded-md border px-1 py-1 text-center font-mono text-xs tabular-nums transition-colors",
              isFail
                ? "border-red-400 bg-red-500/15 font-bold text-red-700 dark:text-red-300"
                : "border-border text-muted-foreground hover:border-brand-copper",
              (disabled || locked) && "cursor-not-allowed opacity-70",
            )}
          >
            {sampleLabel(no)}
            {/* 표본 표시는 한글 한 자: 합 · 불 (화면 검토 M74) */}
            <span className="ml-1">{isFail ? "불" : "합"}</span>
          </button>
        );
      })}
    </div>
  )

