(to: "submitted" | "reviewed" | "approved") => {
    const withOpinion = opinionAt === to;
    if (withOpinion && receipt === null) {
      toast.error("6.1 접수 여부를 고르세요.");
      return;
    }
    if (withOpinion && receipt === false && comment.trim() === "") {
      toast.error("미접수로 정하면 6.3 검토 의견에 그 이유를 적어야 합니다.");
      return;
    }
    const finished =
      sheet === "report"
        ? "결재가 끝났습니다. 부적합이 종결되었습니다."
        : "결재가 끝났습니다.";
    const done = (arrived: string | undefined) =>
      withOpinion && receipt === false
        ? "미접수로 정해 부결되었습니다."
        : to !== "approved" && arrived === "approved"
          ? `${to === "submitted" ? "상신했습니다." : "검토를 마쳤습니다."} ${finished}`
          : to === "submitted"
            ? "상신했습니다."
            : to === "reviewed"
              ? "검토를 마쳤습니다."
              : sheet === "report"
                ? "승인했습니다. 부적합이 종결되었습니다."
                : "승인했습니다.";
    run(
      () =>
        sheet === "occurrence"
          ? transitionNcOccurrence({
              id,
              to,
              receipt_accepted: withOpinion
                ? (receipt ?? undefined)
                : undefined,
              review_comment: withOpinion ? comment.trim() || null : undefined,
            })
          : transitionNcReport({ id, to }),
      done,
    );
  }

